#if FOO
fileprivate extension SyntaxProtocol {
  /// Returns `true` if the tree contains any tokens (either missing or present).
  var hasTokens: Bool {
    let checker = HasTokenChecker(viewMode. all)
    checker.walk(Syntax(self))
    return checker.hasToken
  }
}
#endif

